--
-- Final view structure for view `leaderboard`
--

/*!50001 DROP VIEW IF EXISTS `leaderboard`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_general_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`bdb`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `leaderboard` AS select `B`.`book_id` AS `book_id`,`B`.`image_path` AS `image_path`,`B`.`title` AS `title`,`B`.`author` AS `author`,coalesce(avg(`R`.`rating`),'N/A') AS `avg_rating`,coalesce(count(`R`.`rating_id`),'N/A') AS `totalratings` from (`books` `B` left join `ratings` `R` on(`B`.`book_id` = `R`.`book_id`)) group by `B`.`book_id` order by coalesce(count(`R`.`rating_id`),'N/A') desc,coalesce(avg(`R`.`rating`),'N/A') desc */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;

